<?php
declare(strict_types=1);
namespace app\common\service\app\aigc_copywriting;
use think\facade\Db;
final class CopywritingSeeder {
 public static function catalog():array{return json_decode(file_get_contents(dirname(__DIR__,4).'/apps/aigc_copywriting/data/builtin-tools.json'),true,512,JSON_THROW_ON_ERROR);}
 public static function ensureTenant(int $tenantId):array {if($tenantId<=0)return ['inserted'=>0,'skipped'=>0,'seed_version'=>'1.0.0'];return Db::transaction(function()use($tenantId){$inserted=0;$skipped=0;$categories=[];Db::name('tenant')->where('id',$tenantId)->lock(true)->find();if(CopywritingStore::table('tool')->where('tenant_id',$tenantId)->whereNotNull('builtin_code')->count()>=12&&CopywritingStore::table('page')->where(['tenant_id'=>$tenantId,'page_code'=>'home'])->find())return ['inserted'=>0,'skipped'=>12,'seed_version'=>'1.0.0'];foreach(['风险优化','创作输出','平台图文','内容提取']as $i=>$name){$code=['risk','creation','platform','extraction'][$i];$q=CopywritingStore::table('category')->where(['tenant_id'=>$tenantId,'code'=>$code]);$row=$q->find();$categories[$name]=$row['id']??CopywritingStore::insert('category',['tenant_id'=>$tenantId,'code'=>$code,'name'=>$name,'sort'=>100-$i]);}foreach(self::catalog()as $tool){if(CopywritingStore::table('tool')->where(['tenant_id'=>$tenantId,'builtin_code'=>$tool['code']])->find()){$skipped++;continue;}CopywritingDocument::assertValid($tool['document']);$id=CopywritingStore::insert('tool',['tenant_id'=>$tenantId,'tool_code'=>$tool['code'],'builtin_code'=>$tool['code'],'name'=>$tool['name'],'description'=>$tool['description'],'icon'=>$tool['icon'],'category_id'=>$categories[$tool['category']],'sort'=>100-$inserted]);$page=CopywritingStore::insert('page',['tenant_id'=>$tenantId,'page_code'=>$tool['code'],'kind'=>'tool','tool_id'=>$id,'draft_json'=>CopywritingStore::json($tool['document'])]);$v=CopywritingStore::insert('version',['tenant_id'=>$tenantId,'page_id'=>$page,'version_no'=>1,'document_json'=>CopywritingStore::json($tool['document']),'schema_hash'=>hash('sha256',CopywritingStore::json($tool['document'])),'publish_targets'=>'pc,h5,mp-weixin']);CopywritingStore::table('page')->where('id',$page)->update(['published_version_id'=>$v]);$inserted++;}if(!CopywritingStore::table('page')->where(['tenant_id'=>$tenantId,'page_code'=>'home'])->find()){$home=CopywritingDocument::normalize(['page'=>['title'=>'智能文案','nodes'=>[['id'=>'home-title','name'=>'cw-text','content'=>['text'=>'智能文案'],'styles'=>['base'=>['fontSize'=>['value'=>28,'unit'=>'px'],'fontWeight'=>'700']]],['id'=>'home-categories','name'=>'cw-categories','content'=>['mode'=>'grouped'],'styles'=>[]],['id'=>'home-tools','name'=>'cw-tools','content'=>['mode'=>'grouped'],'styles'=>['base'=>['display'=>'grid','gridTemplateColumns'=>'repeat(3,minmax(0,1fr))','gap'=>['value'=>16,'unit'=>'px']],'breakpoints'=>['mobile'=>['gridTemplateColumns'=>'repeat(2,minmax(0,1fr))']]]]]]]);$page=CopywritingStore::insert('page',['tenant_id'=>$tenantId,'page_code'=>'home','kind'=>'home','draft_json'=>CopywritingStore::json($home)]);$v=CopywritingStore::insert('version',['tenant_id'=>$tenantId,'page_id'=>$page,'version_no'=>1,'document_json'=>CopywritingStore::json($home),'schema_hash'=>hash('sha256',CopywritingStore::json($home)),'publish_targets'=>'pc,h5,mp-weixin']);CopywritingStore::table('page')->where('id',$page)->update(['published_version_id'=>$v]);}return compact('inserted','skipped')+['seed_version'=>'1.0.0'];});}
}
